/**
 * Graph Navigation & Filter HUD Toolbar
 * La Grande Bibliothèque — Milestone 4 (Feature R4)
 * 
 * Provides Category & Tag dropdown filters, search bar, visual toggles,
 * and zoom controls with Airy Design (>=44px touch ergonomics, mobile-responsive).
 */

import React from 'react';
import {
  Search,
  ZoomIn,
  ZoomOut,
  Maximize2,
  Sparkles,
  Layers,
  Ghost,
  X,
  Tag as TagIcon,
  Folder,
} from 'lucide-react';
import { cn } from '../../lib/utils.js';

export interface GraphToolbarProps {
  mode: 'global' | 'contextual';
  searchQuery: string;
  onSearchChange: (q: string) => void;
  selectedCategoryId: string | null;
  onSelectCategory: (catId: string | null) => void;
  categories: Array<{ id: string; name: string; color: string }>;
  selectedTag?: string | null;
  onSelectTag?: (tag: string | null) => void;
  tags?: Array<{ id: string; name: string }>;
  isBreathingActive: boolean;
  onToggleBreathing: () => void;
  showClusters: boolean;
  onToggleClusters: () => void;
  showGhostNodes?: boolean;
  onToggleGhostNodes?: () => void;
  onResetView: () => void;
  onZoomIn: () => void;
  onZoomOut: () => void;
  nodeCount: number;
  edgeCount: number;
  modularity?: number;
  zoomPercentage?: number;
}

export const GraphToolbar: React.FC<GraphToolbarProps> = ({
  mode,
  searchQuery,
  onSearchChange,
  selectedCategoryId,
  onSelectCategory,
  categories = [],
  selectedTag = null,
  onSelectTag,
  tags = [],
  isBreathingActive,
  onToggleBreathing,
  showClusters,
  onToggleClusters,
  showGhostNodes = true,
  onToggleGhostNodes,
  onResetView,
  onZoomIn,
  onZoomOut,
  nodeCount,
  edgeCount,
  modularity = 0,
  zoomPercentage = 100,
}) => {
  return (
    <div
      className="absolute top-3 sm:top-4 left-3 sm:left-4 right-3 sm:right-4 z-20 flex flex-wrap items-center justify-between gap-2.5 pointer-events-none"
      data-testid="graph-toolbar"
    >
      {/* Search, Category & Tag Filters (Left / Center) */}
      <div className="flex flex-wrap items-center gap-2 pointer-events-auto bg-background-surface border border-border rounded-2xl p-1.5 sm:p-2 shadow-xl max-w-[calc(100vw-1.5rem)]">
        {/* Search input */}
        <div className="relative flex items-center min-w-[160px] sm:min-w-[220px] min-h-[44px]">
          <Search className="w-4 h-4 text-foreground-muted absolute left-3.5 pointer-events-none" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder="Filter nodes & tags..."
            aria-label="Filter graph nodes"
            data-testid="graph-search-input"
            className="w-full pl-10 pr-9 py-2 text-sm bg-background-elevated border border-border/80 rounded-xl text-foreground placeholder:text-foreground-subtle focus:outline-none focus:border-accent min-h-[44px]"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => onSearchChange('')}
              className="w-9 h-9 min-h-[36px] min-w-[36px] flex items-center justify-center absolute right-1 text-foreground-muted hover:text-foreground cursor-pointer rounded-lg hover:bg-background-hover"
              title="Clear search"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        {/* Top Category Filter Dropdown */}
        <div className="relative flex items-center min-h-[44px]">
          <label htmlFor="graph-category-filter" className="sr-only">
            Filtrer par catégorie
          </label>
          <div className="relative flex items-center">
            <Folder className="w-4 h-4 text-accent absolute left-3 pointer-events-none" />
            <select
              id="graph-category-filter"
              value={selectedCategoryId || ''}
              onChange={(e) => onSelectCategory(e.target.value ? e.target.value : null)}
              data-testid="graph-category-dropdown"
              className="pl-9 pr-8 py-2 text-xs sm:text-sm font-medium bg-background-elevated hover:bg-background-hover border border-border rounded-xl text-foreground focus:outline-none focus:border-accent cursor-pointer min-h-[44px] appearance-none"
            >
              <option value="">Toutes les catégories</option>
              {categories.map((cat) => (
                <option key={cat.id} value={cat.id}>
                  {cat.name}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Top Tag Filter Dropdown */}
        {tags.length > 0 && onSelectTag && (
          <div className="relative flex items-center min-h-[44px]">
            <label htmlFor="graph-tag-filter" className="sr-only">
              Filtrer par tag
            </label>
            <div className="relative flex items-center">
              <TagIcon className="w-4 h-4 text-accent absolute left-3 pointer-events-none" />
              <select
                id="graph-tag-filter"
                value={selectedTag || ''}
                onChange={(e) => onSelectTag(e.target.value ? e.target.value : null)}
                data-testid="graph-tag-dropdown"
                className="pl-9 pr-8 py-2 text-xs sm:text-sm font-medium bg-background-elevated hover:bg-background-hover border border-border rounded-xl text-foreground focus:outline-none focus:border-accent cursor-pointer min-h-[44px] appearance-none"
              >
                <option value="">Tous les tags</option>
                {tags.map((tag) => (
                  <option key={tag.id} value={tag.name}>
                    #{tag.name}
                  </option>
                ))}
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Visual Toggles & Zoom Controls (Right) */}
      <div className="flex items-center gap-1.5 sm:gap-2 pointer-events-auto bg-background-surface border border-border rounded-2xl p-1.5 sm:p-2 shadow-xl min-h-[44px] max-w-[calc(100vw-1.5rem)]">
        {/* Living Breathing Toggle */}
        <button
          type="button"
          onClick={onToggleBreathing}
          title={isBreathingActive ? 'Suspendre la respiration organique' : 'Reprendre la respiration organique'}
          data-testid="toggle-breathing-btn"
          className={cn(
            'px-3 py-2 rounded-xl text-xs sm:text-sm font-medium flex items-center gap-1.5 transition-colors cursor-pointer min-h-[44px]',
            isBreathingActive
              ? 'bg-accent/15 text-accent border border-accent/30'
              : 'text-foreground-muted hover:bg-background-hover border border-border/40'
          )}
        >
          <Sparkles className={cn('w-4 h-4', isBreathingActive ? 'animate-pulse' : '')} />
          <span className="hidden md:inline">Respiration</span>
        </button>

        {/* Constellation Clusters Toggle */}
        <button
          type="button"
          onClick={onToggleClusters}
          title={showClusters ? 'Masquer les nébuleuses' : 'Afficher les nébuleuses'}
          data-testid="toggle-clusters-btn"
          className={cn(
            'px-3 py-2 rounded-xl text-xs sm:text-sm font-medium flex items-center gap-1.5 transition-colors cursor-pointer min-h-[44px]',
            showClusters
              ? 'bg-accent/15 text-accent border border-accent/30'
              : 'text-foreground-muted hover:bg-background-hover border border-border/40'
          )}
        >
          <Layers className="w-4 h-4" />
          <span className="hidden md:inline">Groupes</span>
        </button>

        {/* Contextual Ghost Nodes Toggle */}
        {mode === 'contextual' && onToggleGhostNodes && (
          <button
            type="button"
            onClick={onToggleGhostNodes}
            title={showGhostNodes ? 'Masquer les noeuds fantômes (2 sauts)' : 'Afficher les noeuds fantômes (2 sauts)'}
            data-testid="toggle-ghost-nodes-btn"
            className={cn(
              'px-3 py-2 rounded-xl text-xs sm:text-sm font-medium flex items-center gap-1.5 transition-colors cursor-pointer min-h-[44px]',
              showGhostNodes
                ? 'bg-accent/15 text-accent border border-accent/30'
                : 'text-foreground-muted hover:bg-background-hover border border-border/40'
            )}
          >
            <Ghost className="w-4 h-4" />
            <span className="hidden md:inline">Fantômes</span>
          </button>
        )}

        <div className="w-[1px] h-6 bg-border mx-0.5 border-border" />

        {/* Zoom Controls */}
        <button
          type="button"
          onClick={onZoomOut}
          title="Dézoomer (-)"
          data-testid="zoom-out-btn"
          className="w-11 h-11 min-h-[44px] min-w-[44px] flex items-center justify-center p-2 text-foreground-muted hover:text-foreground hover:bg-background-hover rounded-xl transition-colors cursor-pointer"
        >
          <ZoomOut className="w-4 h-4" />
        </button>

        <span className="text-xs sm:text-sm text-foreground-subtle min-w-[40px] text-center font-mono font-medium">
          {zoomPercentage}%
        </span>

        <button
          type="button"
          onClick={onZoomIn}
          title="Zoomer (+)"
          data-testid="zoom-in-btn"
          className="w-11 h-11 min-h-[44px] min-w-[44px] flex items-center justify-center p-2 text-foreground-muted hover:text-foreground hover:bg-background-hover rounded-xl transition-colors cursor-pointer"
        >
          <ZoomIn className="w-4 h-4" />
        </button>

        <button
          type="button"
          onClick={onResetView}
          title="Réinitialiser la vue"
          data-testid="reset-view-btn"
          className="w-11 h-11 min-h-[44px] min-w-[44px] flex items-center justify-center p-2 text-foreground-muted hover:text-foreground hover:bg-background-hover rounded-xl transition-colors cursor-pointer"
        >
          <Maximize2 className="w-4 h-4" />
        </button>

        {/* Stats badge */}
        <div className="hidden xl:flex items-center gap-2 pl-2.5 border-l border-border text-xs text-foreground-subtle font-mono">
          <span>{nodeCount} noeuds</span>
          <span>•</span>
          <span>{edgeCount} liens</span>
          {modularity > 0 && (
            <>
              <span>•</span>
              <span title="Modularité Louvain Newman-Girvan">Q = {modularity.toFixed(2)}</span>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default GraphToolbar;
