import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import type { User, LoginCredentials, RegisterCredentials } from '../types/auth.js';
import { api } from '../lib/api.js';

export interface AuthContextValue {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (credentials: LoginCredentials) => Promise<void>;
  register: (credentials: RegisterCredentials) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
}

const TOKEN_KEY = 'gb_token';

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(() => {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        return localStorage.getItem(TOKEN_KEY);
      }
    } catch {
      // Ignore
    }
    return null;
  });
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const refreshUser = useCallback(async () => {
    try {
      const response = await api.get<{ user: User }>('/api/auth/me');
      setUser(response.user);
    } catch {
      setUser(null);
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.removeItem(TOKEN_KEY);
        }
      } catch {
        // Ignore
      }
      setToken(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshUser();
  }, [refreshUser]);

  const login = async (credentials: LoginCredentials) => {
    setIsLoading(true);
    try {
      const response = await api.post<{ user: User; token: string }>('/api/auth/login', credentials);
      setUser(response.user);
      setToken(response.token);
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.setItem(TOKEN_KEY, response.token);
        }
      } catch {
        // Ignore
      }
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (credentials: RegisterCredentials) => {
    setIsLoading(true);
    try {
      const response = await api.post<{ user: User; token: string }>('/api/auth/register', credentials);
      setUser(response.user);
      setToken(response.token);
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.setItem(TOKEN_KEY, response.token);
        }
      } catch {
        // Ignore
      }
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      await api.post('/api/auth/logout');
    } catch {
      // Continue cleanup even if server request fails
    } finally {
      setUser(null);
      setToken(null);
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.removeItem(TOKEN_KEY);
        }
      } catch {
        // Ignore
      }
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isLoading,
        isAuthenticated: !!user,
        login,
        register,
        logout,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextValue => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
