import React from 'react';
import { Sun, Moon } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext.js';
import { cn } from '../../lib/utils.js';

interface ThemeToggleProps {
  className?: string;
  variant?: 'icon' | 'pill';
}

export const ThemeToggle: React.FC<ThemeToggleProps> = ({ className, variant = 'icon' }) => {
  const { theme, toggleTheme } = useTheme();
  const isDark = theme === 'dark';

  return (
    <button
      type="button"
      onClick={toggleTheme}
      aria-label={`Switch to ${isDark ? 'light' : 'dark'} mode`}
      data-testid="theme-toggle"
      className={cn(
        'relative inline-flex items-center justify-center transition-colors duration-200 rounded-lg cursor-pointer',
        'focus:outline-none focus:ring-2 focus:ring-accent focus:ring-offset-1 focus:ring-offset-background',
        variant === 'icon' && 'p-2 text-foreground-muted hover:text-foreground hover:bg-background-hover',
        variant === 'pill' && 'px-3 py-1.5 text-xs font-medium bg-background-elevated hover:bg-background-hover text-foreground gap-2 border border-border',
        className
      )}
    >
      {isDark ? (
        <Sun className="w-4 h-4 text-amber-400 transition-transform duration-200 rotate-0 hover:rotate-45" />
      ) : (
        <Moon className="w-4 h-4 text-indigo-500 transition-transform duration-200 -rotate-12 hover:rotate-0" />
      )}
      {variant === 'pill' && <span>{isDark ? 'Light' : 'Dark'}</span>}
    </button>
  );
};
