import React, { useState, useMemo } from 'react';
import type { EmbedBlockContent, EmbedProvider } from '../../../types/block.js';
import {
  ExternalLink,
  Youtube,
  Music,
  Globe,
  Edit2,
  Check,
} from 'lucide-react';

interface EmbedBlockProps {
  content: EmbedBlockContent;
  onChange: (content: EmbedBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

export function parseEmbedUrl(rawUrl: string): {
  provider: EmbedProvider;
  embedUrl: string;
  sanitizedUrl: string;
} {
  const trimmed = rawUrl.trim();
  if (!trimmed.startsWith('http://') && !trimmed.startsWith('https://')) {
    return { provider: 'generic', embedUrl: '', sanitizedUrl: '' };
  }

  // 1. Spotify
  const spotifyMatch = trimmed.match(/open\.spotify\.com\/(track|album|playlist|artist|episode)\/([a-zA-Z0-9]+)/);
  if (spotifyMatch) {
    return {
      provider: 'spotify',
      embedUrl: `https://open.spotify.com/embed/${spotifyMatch[1]}/${spotifyMatch[2]}`,
      sanitizedUrl: trimmed,
    };
  }

  // 2. YouTube
  const ytMatch = trimmed.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([\w-]{11})/);
  if (ytMatch) {
    return {
      provider: 'youtube',
      embedUrl: `https://www.youtube-nocookie.com/embed/${ytMatch[1]}`,
      sanitizedUrl: trimmed,
    };
  }

  // 3. SoundCloud
  if (trimmed.includes('soundcloud.com')) {
    return {
      provider: 'soundcloud',
      embedUrl: `https://w.soundcloud.com/player/?url=${encodeURIComponent(trimmed)}&color=%23ff5500&auto_play=false&hide_related=true&show_comments=false&show_user=true&show_reposts=false&show_teaser=false`,
      sanitizedUrl: trimmed,
    };
  }

  return {
    provider: 'generic',
    embedUrl: trimmed,
    sanitizedUrl: trimmed,
  };
}

export const EmbedBlock: React.FC<EmbedBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const [urlInput, setUrlInput] = useState(content.url || '');
  const [isEditing, setIsEditing] = useState(!content.url);

  const parsed = useMemo(() => parseEmbedUrl(content.url || ''), [content.url]);
  const provider = content.provider || parsed.provider;
  const embedSrc = content.embedUrl || parsed.embedUrl;

  const handleApply = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!urlInput.trim()) return;

    const { provider: autoProvider, embedUrl: autoEmbedUrl, sanitizedUrl } = parseEmbedUrl(urlInput);

    let defaultTitle = sanitizedUrl;
    try {
      defaultTitle = new URL(sanitizedUrl).hostname;
    } catch {}

    onChange({
      url: sanitizedUrl,
      provider: autoProvider,
      embedUrl: autoEmbedUrl,
      title: content.title || defaultTitle,
      description: content.description || 'External content reference',
    });
    setIsEditing(false);
  };

  return (
    <div className="w-full rounded-xl overflow-hidden flex flex-col transition-all">
      {/* Header bar - visible on hover/focus */}
      {isToolbarVisible && (
        <div className="flex items-center justify-between p-2.5 bg-background-surface border border-border rounded-t-xl text-foreground-muted select-none animate-in fade-in duration-150">
          <div className="flex items-center gap-2">
            {provider === 'youtube' && <Youtube className="w-4 h-4 text-red-500" />}
            {provider === 'spotify' && <Music className="w-4 h-4 text-emerald-400" />}
            {provider === 'soundcloud' && <Music className="w-4 h-4 text-amber-500" />}
            {provider === 'generic' && <Globe className="w-4 h-4 text-accent" />}
            <span className="font-mono text-xs font-bold uppercase tracking-wider text-foreground">
              Intégration {provider}
            </span>
          </div>

          {!readOnly && (
            <button
              type="button"
              onClick={() => setIsEditing(!isEditing)}
              className="flex items-center gap-1.5 px-3 py-2 min-h-[44px] rounded-lg hover:bg-background-hover hover:text-foreground text-xs font-mono transition-colors cursor-pointer"
              title="Modifier l'URL"
            >
              <Edit2 className="w-3.5 h-3.5" />
              <span className="hidden sm:inline font-semibold">{isEditing ? 'Fermer' : 'Modifier URL'}</span>
            </button>
          )}
        </div>
      )}

      {/* URL Input Form */}
      {isEditing && !readOnly && isToolbarVisible && (
        <form onSubmit={handleApply} className="p-3 bg-background-surface/90 border-x border-b border-border flex gap-2 animate-in fade-in">
          <input
            type="text"
            value={urlInput}
            onChange={(e) => setUrlInput(e.target.value)}
            placeholder="Lien Spotify, YouTube, SoundCloud ou Web (https://...)"
            className="flex-1 px-3 py-2 min-h-[44px] bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-accent font-mono"
          />
          <button
            type="submit"
            disabled={!urlInput.trim()}
            className="flex items-center gap-1.5 px-4 py-2 min-h-[44px] bg-accent text-accent-foreground text-xs font-bold rounded-lg hover:opacity-90 transition-opacity disabled:opacity-40 cursor-pointer"
          >
            <Check className="w-4 h-4" />
            <span>Appliquer</span>
          </button>
        </form>
      )}

      {/* Embed Display Body */}
      <div className={`p-3 ${isToolbarVisible ? 'border-x border-b border-border rounded-b-xl bg-card/40' : ''}`}>
        {!content.url ? (
          <div className="py-8 text-center border-2 border-dashed border-border rounded-xl p-6 bg-background/30">
            <Globe className="w-8 h-8 mx-auto text-foreground-muted mb-2 animate-pulse" />
            <p className="text-sm font-mono text-foreground font-semibold">Aucun lien intégré configuré</p>
            <p className="text-xs text-foreground-muted mt-1 max-w-sm mx-auto">
              Prend en charge YouTube, Spotify, SoundCloud et les cartes OpenGraph Web.
            </p>
          </div>
        ) : (
          <>
            {/* 1. YOUTUBE IFRAME */}
            {provider === 'youtube' && embedSrc && (
              <div className="relative aspect-video w-full rounded-xl overflow-hidden border border-border bg-black">
                <iframe
                  src={embedSrc}
                  title={content.title || 'Lecteur YouTube'}
                  className="w-full h-full border-0 border-border"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                />
              </div>
            )}

            {/* 2. SPOTIFY IFRAME */}
            {provider === 'spotify' && embedSrc && (
              <div className="w-full rounded-xl overflow-hidden border border-border bg-black">
                <iframe
                  src={embedSrc}
                  title={content.title || 'Lecteur Spotify'}
                  className="w-full h-[152px] border-0 border-border"
                  allow="encrypted-media"
                />
              </div>
            )}

            {/* 3. SOUNDCLOUD IFRAME */}
            {provider === 'soundcloud' && embedSrc && (
              <div className="w-full rounded-xl overflow-hidden border border-border bg-background">
                <iframe
                  src={embedSrc}
                  title={content.title || 'Lecteur SoundCloud'}
                  className="w-full h-[166px] border-0 border-border"
                  scrolling="no"
                  allow="autoplay"
                />
              </div>
            )}

            {/* 4. GENERIC OPENGRAPH CARD */}
            {provider === 'generic' && (
              <div className="p-4 bg-background-surface border border-border rounded-xl hover:border-accent/60 transition-colors flex flex-col sm:flex-row gap-4 items-start justify-between">
                {content.thumbnailUrl && (
                  <img
                    src={content.thumbnailUrl}
                    alt={content.title || 'Aperçu'}
                    className="w-full sm:w-32 h-24 object-cover rounded-lg border border-border"
                  />
                )}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <Globe className="w-4 h-4 text-accent" />
                    <span className="text-xs font-mono text-accent font-semibold truncate">
                      {content.url}
                    </span>
                  </div>
                  <h4 className="text-base font-bold text-foreground line-clamp-1">
                    {content.title || content.url}
                  </h4>
                  <p className="text-xs text-foreground-muted mt-1 line-clamp-2 leading-relaxed">
                    {content.description || 'Lien web externe'}
                  </p>
                </div>
                <a
                  href={content.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="self-end sm:self-center p-3 min-h-[44px] min-w-[44px] flex items-center justify-center bg-background hover:bg-background-hover border border-border rounded-lg text-foreground hover:text-accent transition-colors cursor-pointer"
                  title="Ouvrir le lien"
                >
                  <ExternalLink className="w-4 h-4" />
                </a>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};
