import React, { useState } from 'react';
import type { Block, BlockType, PresenceUser } from '../../types/block.js';
import {
  GripVertical,
  Type,
  FileText,
  PenTool,
  CheckSquare,
  Table as TableIcon,
  Music,
  Globe,
  Code2,
  Trash2,
  Copy,
  ChevronUp,
  ChevronDown,
  Folder,
} from 'lucide-react';
import { RichTextBlock } from './blocks/RichTextBlock.js';
import { MarkdownBlock } from './blocks/MarkdownBlock.js';
import { DrawingBlock } from './blocks/DrawingBlock.js';
import { ChecklistBlock } from './blocks/ChecklistBlock.js';
import { TableBlock } from './blocks/TableBlock.js';
import { MediaBlock } from './blocks/MediaBlock.js';
import { EmbedBlock } from './blocks/EmbedBlock.js';
import { CodeBlock } from './blocks/CodeBlock.js';

interface BlockItemProps {
  block: Block;
  index: number;
  totalBlocks: number;
  onChange: (content: any) => void;
  onDelete: () => void;
  onDuplicate: () => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  onDragStart?: (e: React.DragEvent) => void;
  onDragOver?: (e: React.DragEvent) => void;
  onDrop?: (e: React.DragEvent) => void;
  activeCollaborator?: PresenceUser;
  readOnly?: boolean;
  isActive?: boolean;
  onSelectBlock?: (blockId: string) => void;
}

export const BLOCK_META: Record<BlockType, { label: string; icon: React.FC<{ className?: string }>; color: string }> = {
  rich_text: { label: 'Texte riche', icon: Type, color: 'text-sky-400 bg-sky-500/10 border-sky-500/20' },
  markdown: { label: 'Markdown', icon: FileText, color: 'text-purple-400 bg-purple-500/10 border-purple-500/20' },
  drawing: { label: 'Dessin', icon: PenTool, color: 'text-amber-400 bg-amber-500/10 border-amber-500/20' },
  checklist: { label: 'Liste de tâches', icon: CheckSquare, color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' },
  table: { label: 'Tableau', icon: TableIcon, color: 'text-blue-400 bg-blue-500/10 border-blue-500/20' },
  media: { label: 'Média & Audio', icon: Music, color: 'text-pink-400 bg-pink-500/10 border-pink-500/20' },
  embed: { label: 'Intégration', icon: Globe, color: 'text-indigo-400 bg-indigo-500/10 border-indigo-500/20' },
  code: { label: 'Code', icon: Code2, color: 'text-emerald-300 bg-emerald-500/10 border-emerald-500/20' },
  subproject: { label: 'Sous-page / Feuille', icon: Folder, color: 'text-amber-400 bg-amber-500/10 border-amber-500/20' },
};

export const BlockItem: React.FC<BlockItemProps> = ({
  block,
  index,
  totalBlocks,
  onChange,
  onDelete,
  onDuplicate,
  onMoveUp,
  onMoveDown,
  onDragStart,
  onDragOver,
  onDrop,
  activeCollaborator,
  readOnly = false,
  isActive = false,
  onSelectBlock,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const isToolbarVisible = !readOnly && (isActive || isHovered);

  const meta = BLOCK_META[block.type] || {
    label: block.type,
    icon: FileText,
    color: 'text-foreground bg-background-surface border-border',
  };
  const IconComponent = meta.icon;

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!readOnly && onSelectBlock) {
      onSelectBlock(block.id);
    }
  };

  return (
    <div
      data-testid={`block-item-${block.id}`}
      draggable={!readOnly}
      onDragStart={onDragStart}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={handleClick}
      className={`group/block relative rounded-xl transition-all duration-200 ${
        activeCollaborator
          ? 'ring-2 border-transparent bg-card shadow-md'
          : isActive
          ? 'bg-card/90 border border-border/80 ring-1 ring-accent/30 shadow-md'
          : isHovered
          ? 'bg-card/30 border border-border/50 shadow-sm'
          : 'bg-transparent border border-transparent'
      }`}
      style={{
        boxShadow: activeCollaborator ? `0 0 0 2px ${activeCollaborator.color}` : undefined,
      }}
    >
      {/* Notion-Style Block Header Bar: Appears ONLY on hover or when active */}
      {isToolbarVisible && (
        <div className="flex items-center justify-between px-3 py-1.5 bg-background-surface/80 border-b border-border/70 rounded-t-xl select-none animate-in fade-in duration-150">
          {/* Left: Drag handle & Type Badge */}
          <div className="flex items-center gap-2">
            {!readOnly && (
              <div
                className="cursor-grab active:cursor-grabbing text-foreground-muted hover:text-foreground p-1 rounded-md transition-colors min-h-[36px] min-w-[36px] flex items-center justify-center"
                title="Glisser pour réordonner"
                aria-label="Glisser pour réordonner"
              >
                <GripVertical className="w-4 h-4" />
              </div>
            )}

            <div
              className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg border text-xs font-mono font-medium ${meta.color} border-border`}
            >
              <IconComponent className="w-3.5 h-3.5" />
              <span>{meta.label}</span>
            </div>

            {activeCollaborator && (
              <span
                className="flex items-center gap-1 text-xs font-mono px-2.5 py-1 rounded-full font-bold animate-pulse text-background"
                style={{ backgroundColor: activeCollaborator.color }}
              >
                {activeCollaborator.userName} modifie
              </span>
            )}
          </div>

          {/* Right: Actions menu */}
          {!readOnly && (
            <div className="flex items-center gap-1">
              {onMoveUp && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onMoveUp();
                  }}
                  disabled={index === 0}
                  className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground hover:bg-background disabled:opacity-20 disabled:cursor-not-allowed transition-colors cursor-pointer"
                  title="Déplacer vers le haut"
                  aria-label="Déplacer vers le haut"
                >
                  <ChevronUp className="w-4 h-4" />
                </button>
              )}

              {onMoveDown && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onMoveDown();
                  }}
                  disabled={index === totalBlocks - 1}
                  className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground hover:bg-background disabled:opacity-20 disabled:cursor-not-allowed transition-colors cursor-pointer"
                  title="Déplacer vers le bas"
                  aria-label="Déplacer vers le bas"
                >
                  <ChevronDown className="w-4 h-4" />
                </button>
              )}

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onDuplicate();
                }}
                className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground hover:bg-background transition-colors cursor-pointer"
                title="Dupliquer"
                aria-label="Dupliquer"
              >
                <Copy className="w-4 h-4" />
              </button>

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete();
                }}
                className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg text-foreground-muted hover:text-destructive hover:bg-background transition-colors cursor-pointer"
                title="Supprimer"
                aria-label="Supprimer"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      )}

      {/* Polymorphic Content Component Body */}
      <div className={isToolbarVisible ? 'p-2' : 'py-1'}>
        {block.type === 'rich_text' && (
          <RichTextBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'markdown' && (
          <MarkdownBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'drawing' && (
          <DrawingBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'checklist' && (
          <ChecklistBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'table' && (
          <TableBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'media' && (
          <MediaBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'embed' && (
          <EmbedBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'code' && (
          <CodeBlock
            content={block.content as any}
            onChange={onChange}
            readOnly={readOnly}
            isToolbarVisible={isToolbarVisible}
          />
        )}
        {block.type === 'subproject' && (
          <div className="flex items-center justify-between gap-3 p-3 bg-background-surface/40 border border-border/20 rounded-xl">
            <div className="flex items-center gap-2.5 min-w-0">
              <Folder className="w-5 h-5 text-amber-400" />
              <span className="text-sm font-semibold text-foreground">
                Sous-page (accessible en mode canva)
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
