import React, { useState, useRef, useMemo } from 'react';
import type { CodeBlockContent, CodeLanguage } from '../../../types/block.js';
import { Code2, Copy, Check } from 'lucide-react';

interface CodeBlockProps {
  content: CodeBlockContent;
  onChange: (content: CodeBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

const SUPPORTED_LANGUAGES: Array<{ value: CodeLanguage; label: string }> = [
  { value: 'typescript', label: 'TypeScript' },
  { value: 'javascript', label: 'JavaScript' },
  { value: 'python', label: 'Python' },
  { value: 'rust', label: 'Rust' },
  { value: 'css', label: 'CSS' },
  { value: 'html', label: 'HTML' },
  { value: 'sql', label: 'SQL' },
  { value: 'json', label: 'JSON' },
  { value: 'markdown', label: 'Markdown' },
  { value: 'plaintext', label: 'Plain Text' },
];

function highlightCode(code: string, language: CodeLanguage): string {
  if (!code) return '';

  let escaped = code
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  if (language === 'plaintext') {
    return escaped;
  }

  escaped = escaped.replace(/(\/\/[^\n]*|\/\*[\s\S]*?\*\/|#[^\n]*)/g, '<span class="text-zinc-500 italic">$1</span>');
  escaped = escaped.replace(/(".*?"|'.*?'|`.*?`)/g, '<span class="text-emerald-400">$1</span>');
  escaped = escaped.replace(/\b(\d+(\.\d+)?)\b/g, '<span class="text-amber-400">$1</span>');

  const keywords = [
    'const', 'let', 'var', 'function', 'return', 'if', 'else', 'for', 'while',
    'import', 'from', 'export', 'default', 'class', 'extends', 'async', 'await',
    'def', 'class', 'in', 'is', 'not', 'and', 'or', 'lambda', 'self', 'None', 'True', 'False',
    'fn', 'pub', 'mut', 'impl', 'struct', 'enum', 'trait', 'match', 'use', 'mod', 'Vec', 'String', 'i32', 'f32', 'u32',
    'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'FROM', 'WHERE', 'JOIN', 'TABLE', 'CREATE',
  ];
  const kwRegex = new RegExp(`\\b(${keywords.join('|')})\\b`, 'g');
  escaped = escaped.replace(kwRegex, '<span class="text-purple-400 font-semibold">$1</span>');

  escaped = escaped.replace(/\b([a-zA-Z0-9_$]+)(?=\s*\()/g, '<span class="text-sky-400">$1</span>');

  const types = ['string', 'number', 'boolean', 'any', 'void', 'Promise', 'Array', 'Object', 'Record'];
  const typeRegex = new RegExp(`\\b(${types.join('|')})\\b`, 'g');
  escaped = escaped.replace(typeRegex, '<span class="text-yellow-300 font-medium">$1</span>');

  return escaped;
}

export const CodeBlock: React.FC<CodeBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const language = content.language || 'typescript';
  const code = content.code || '';
  const [copied, setCopied] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const lines = useMemo(() => {
    return code.split('\n');
  }, [code]);

  const highlightedHtml = useMemo(() => {
    return highlightCode(code, language);
  }, [code, language]);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (readOnly) return;
    if (e.key === 'Tab') {
      e.preventDefault();
      const textarea = textareaRef.current;
      if (!textarea) return;

      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const newCode = code.substring(0, start) + '  ' + code.substring(end);

      onChange({ language, code: newCode });

      setTimeout(() => {
        textarea.selectionStart = textarea.selectionEnd = start + 2;
      }, 0);
    }
  };

  return (
    <div className="w-full rounded-xl overflow-hidden flex flex-col transition-all">
      {/* Header bar - visible on hover/focus */}
      {isToolbarVisible && (
        <div className="flex items-center justify-between px-3 py-2 bg-background-surface border border-border rounded-t-xl text-foreground-muted select-none animate-in fade-in duration-150">
          <div className="flex items-center gap-2">
            <Code2 className="w-4 h-4 text-emerald-400" />
            <span className="font-mono text-xs font-bold uppercase tracking-wider text-foreground">
              Extrait de code
            </span>

            <select
              disabled={readOnly}
              value={language}
              onChange={(e) => onChange({ language: e.target.value as CodeLanguage, code })}
              className="bg-background border border-border rounded-lg px-2.5 py-1 min-h-[36px] text-xs font-mono text-foreground focus:outline-none focus:ring-1 focus:ring-accent cursor-pointer"
            >
              {SUPPORTED_LANGUAGES.map((lang) => (
                <option key={lang.value} value={lang.value}>
                  {lang.label}
                </option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs font-mono text-foreground-muted hidden sm:inline">
              {lines.length} {lines.length === 1 ? 'ligne' : 'lignes'}
            </span>
            <button
              type="button"
              onClick={handleCopy}
              className="flex items-center gap-1.5 px-3 py-1.5 min-h-[44px] bg-background hover:bg-background-hover border border-border rounded-lg text-xs font-mono text-foreground transition-colors cursor-pointer"
              title="Copier le code"
            >
              {copied ? (
                <>
                  <Check className="w-4 h-4 text-emerald-400" />
                  <span className="text-xs text-emerald-400 font-bold">Copié !</span>
                </>
              ) : (
                <>
                  <Copy className="w-4 h-4" />
                  <span className="text-xs font-semibold">Copier</span>
                </>
              )}
            </button>
          </div>
        </div>
      )}

      {/* Editor Body with Line Numbers */}
      <div className={`relative flex min-h-[140px] max-h-[550px] overflow-auto font-mono text-sm leading-relaxed bg-[#0d0d12] border border-border/80 ${
        isToolbarVisible ? 'border-t-0 rounded-b-xl' : 'rounded-xl'
      }`}>
        {/* Line Numbers Gutter */}
        <div className="py-3 px-2.5 bg-background-surface/40 text-foreground-muted/50 text-right select-none border-r border-border/50 min-w-[3rem]">
          {lines.map((_, idx) => (
            <div key={idx} className="h-6">
              {idx + 1}
            </div>
          ))}
        </div>

        {/* Code Input & Highlight Overlay */}
        <div className="relative flex-1 p-3">
          {readOnly || !isToolbarVisible ? (
            <pre
              dangerouslySetInnerHTML={{ __html: highlightedHtml || '<span class="text-zinc-600">// Bloc de code vide</span>' }}
              className="font-mono text-sm text-zinc-100 whitespace-pre-wrap break-all m-0"
              style={{ lineHeight: '1.5rem' }}
            />
          ) : (
            <textarea
              ref={textareaRef}
              value={code}
              onChange={(e) => onChange({ language, code: e.target.value })}
              onKeyDown={handleKeyDown}
              placeholder={`// Écrivez du code ${language} ici...`}
              spellCheck={false}
              className="w-full h-full min-h-[120px] bg-transparent text-foreground font-mono text-sm leading-relaxed focus:outline-none resize-none whitespace-pre"
              style={{ lineHeight: '1.5rem' }}
            />
          )}
        </div>
      </div>
    </div>
  );
};
