import React, { createContext, useContext, useEffect, useRef, useState, useCallback } from 'react';
import type { PresenceUser, PresenceCursor, Block } from '../types/block.js';
import { getUserColor } from '../types/block.js';
import { useAuth } from './AuthContext.js';

interface WebSocketContextType {
  isConnected: boolean;
  activeUsers: PresenceUser[];
  sendCursorMove: (x: number, y: number, blockId?: string) => void;
  sendBlockUpdate: (blockId: string, content?: any, order?: number, canvasPosition?: any, version?: number) => void;
  onRemoteBlockUpdate?: (data: { blockId: string; content?: any; order?: number; canvasPosition?: any; version: number; userId: string }) => void;
  registerBlockUpdateListener: (listener: (data: any) => void) => () => void;
}

const WebSocketContext = createContext<WebSocketContextType | null>(null);

interface WebSocketProviderProps {
  projectId: string;
  children: React.ReactNode;
}

export const WebSocketProvider: React.FC<WebSocketProviderProps> = ({ projectId, children }) => {
  const { user } = useAuth();
  const [isConnected, setIsConnected] = useState(false);
  const [activeUsers, setActiveUsers] = useState<PresenceUser[]>([]);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<any>(null);
  const blockUpdateListenersRef = useRef<Set<(data: any) => void>>(new Set());
  const lastCursorSentRef = useRef<number>(0);

  const connect = useCallback(() => {
    if (!projectId || !user) return;

    // Determine WS URL
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.host || 'localhost:3000';
    const pathname = window.location.pathname;
    const wsUrl = pathname.startsWith('/ohara')
      ? `${protocol}//${host}/ohara/ws`
      : `${protocol}//${host}/ws`;

    try {
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        setIsConnected(true);
        // Send join_project payload
        const joinMsg = {
          type: 'join_project',
          projectId,
          userId: user.id,
          userName: user.name || user.email.split('@')[0],
        };
        ws.send(JSON.stringify(joinMsg));
      };

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);

          switch (msg.type) {
            case 'presence_update': {
              const users: PresenceUser[] = (msg.activeUsers || [])
                .filter((u: any) => u.userId !== user.id)
                .map((u: any) => ({
                  userId: u.userId,
                  userName: u.userName || 'Artist',
                  color: u.color || getUserColor(u.userId),
                  cursor: u.cursor,
                  lastUpdated: Date.now(),
                }));
              setActiveUsers(users);
              break;
            }

            case 'cursor_move': {
              if (msg.userId === user.id) break;
              setActiveUsers((prev) => {
                const existing = prev.find((u) => u.userId === msg.userId);
                if (existing) {
                  return prev.map((u) =>
                    u.userId === msg.userId
                      ? {
                          ...u,
                          cursor: { x: msg.x, y: msg.y, blockId: msg.blockId },
                          lastUpdated: Date.now(),
                        }
                      : u
                  );
                } else {
                  return [
                    ...prev,
                    {
                      userId: msg.userId,
                      userName: msg.userName || 'Artist',
                      color: getUserColor(msg.userId),
                      cursor: { x: msg.x, y: msg.y, blockId: msg.blockId },
                      lastUpdated: Date.now(),
                    },
                  ];
                }
              });
              break;
            }

            case 'user_joined': {
              if (msg.user && msg.user.userId !== user.id) {
                setActiveUsers((prev) => {
                  if (prev.some((u) => u.userId === msg.user.userId)) return prev;
                  return [
                    ...prev,
                    {
                      userId: msg.user.userId,
                      userName: msg.user.userName,
                      color: msg.user.color || getUserColor(msg.user.userId),
                      lastUpdated: Date.now(),
                    },
                  ];
                });
              }
              break;
            }

            case 'user_left': {
              if (msg.userId) {
                setActiveUsers((prev) => prev.filter((u) => u.userId !== msg.userId));
              }
              break;
            }

            case 'block_updated': {
              // Notify registered block update listeners
              blockUpdateListenersRef.current.forEach((listener) => {
                listener(msg);
              });
              break;
            }

            default:
              break;
          }
        } catch {
          // Ignore malformed WS packets
        }
      };

      ws.onclose = () => {
        setIsConnected(false);
        // Auto-reconnect after 3s
        reconnectTimeoutRef.current = setTimeout(() => {
          connect();
        }, 3000);
      };

      ws.onerror = () => {
        setIsConnected(false);
      };
    } catch {
      setIsConnected(false);
    }
  }, [projectId, user]);

  useEffect(() => {
    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        try {
          wsRef.current.send(JSON.stringify({ type: 'leave_project', projectId }));
          wsRef.current.close();
        } catch {}
      }
    };
  }, [connect, projectId]);

  // Throttled cursor broadcast
  const sendCursorMove = useCallback(
    (x: number, y: number, blockId?: string) => {
      const now = Date.now();
      if (now - lastCursorSentRef.current < 40) return; // 25 fps max throttle
      lastCursorSentRef.current = now;

      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(
          JSON.stringify({
            type: 'cursor_move',
            projectId,
            x,
            y,
            blockId,
          })
        );
      }
    },
    [projectId]
  );

  // Broadcast block update over WebSocket
  const sendBlockUpdate = useCallback(
    (blockId: string, content?: any, order?: number, canvasPosition?: any, version: number = 1) => {
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(
          JSON.stringify({
            type: 'block_update',
            projectId,
            blockId,
            content,
            order,
            canvasPosition,
            version,
          })
        );
      }
    },
    [projectId]
  );

  const registerBlockUpdateListener = useCallback((listener: (data: any) => void) => {
    blockUpdateListenersRef.current.add(listener);
    return () => {
      blockUpdateListenersRef.current.delete(listener);
    };
  }, []);

  return (
    <WebSocketContext.Provider
      value={{
        isConnected,
        activeUsers,
        sendCursorMove,
        sendBlockUpdate,
        registerBlockUpdateListener,
      }}
    >
      {children}
    </WebSocketContext.Provider>
  );
};

export const useWebSocket = () => {
  const context = useContext(WebSocketContext);
  if (!context) {
    // Fallback if not inside WebSocketProvider
    return {
      isConnected: false,
      activeUsers: [],
      sendCursorMove: () => {},
      sendBlockUpdate: () => {},
      registerBlockUpdateListener: () => () => {},
    };
  }
  return context;
};
