/**
 * Organic Living Breathing Motion Physics & Geometric Transform Layer
 * La Grande Bibliothèque — Milestone 4 (Feature 20)
 * 
 * Implements:
 * 1. Superimposed displacement separation: x_render(t) = x_sim + delta(t)
 * 2. Deterministic Golden Angle Phase Hashing (137.507764 deg)
 * 3. Multi-harmonic traveling wave displacement
 * 4. Degree-proportional node radius scaling and breathing pulsation
 * 5. Affine 2D Screen-to-World and World-to-Screen coordinate transforms
 */

export interface RenderPositionAndRadius {
  x: number;
  y: number;
  r: number;
  dx: number;
  dy: number;
}

/**
 * Deterministic polynomial rolling hash for string IDs.
 */
export function hashStringToInt(str: string): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0; // Convert to 32-bit integer
  }
  return Math.abs(hash);
}

/**
 * Computes organic breathing displacement and radius pulsation for a single node at time t.
 * Pure mathematical function: leaves base physical coordinates unmodified.
 */
export function computeOrganicBreathingOffset(
  nodeId: string,
  basePos: { x: number; y: number },
  timeSec: number,
  degree: number = 0,
  minDegree: number = 0,
  maxDegree: number = 10
): { x: number; y: number; r: number; dx: number; dy: number } {
  const hash = hashStringToInt(nodeId);
  const phi = (hash * (137.5 * (Math.PI / 180))) % (2 * Math.PI);

  // Dual-harmonic traveling wave displacement (Max delta <= 5.0 px)
  const dx = 3.5 * Math.sin(0.5 * timeSec + phi) + 1.5 * Math.cos(1.15 * timeSec + phi);
  const dy = 3.5 * Math.cos(0.5 * timeSec + phi) + 1.5 * Math.sin(1.15 * timeSec + phi);

  // Degree-proportional base radius (3px to 8px)
  const minR = 3.0;
  const maxR = 8.0;
  const range = maxDegree > minDegree ? maxDegree - minDegree : 1;
  const degNorm = (Math.sqrt(Math.max(0, degree)) - Math.sqrt(Math.max(0, minDegree))) / (Math.sqrt(range) + 0.001);
  const baseR = minR + (maxR - minR) * Math.min(1.0, Math.max(0.0, degNorm));

  // Subtle radius pulsation (5% amplitude at 0.5 rad/s)
  const r = baseR * (1.0 + 0.05 * Math.sin(0.5 * timeSec + phi));

  return {
    x: basePos.x + dx,
    y: basePos.y + dy,
    r,
    dx,
    dy,
  };
}

/**
 * 2D Affine Viewport Mapping: World Space -> Screen Space
 */
export function affineTransformWorldToScreen(
  world: { x: number; y: number },
  pan: { x: number; y: number },
  zoom: number
): { x: number; y: number } {
  return {
    x: (world.x + pan.x) * zoom,
    y: (world.y + pan.y) * zoom,
  };
}

/**
 * 2D Affine Viewport Mapping: Screen Space -> World Space
 */
export function affineTransformScreenToWorld(
  screen: { x: number; y: number },
  pan: { x: number; y: number },
  zoom: number
): { x: number; y: number } {
  return {
    x: screen.x / zoom - pan.x,
    y: screen.y / zoom - pan.y,
  };
}
