export const BLOCK_TYPES = [
  'rich_text',
  'markdown',
  'drawing',
  'checklist',
  'table',
  'media',
  'embed',
  'code',
  'subproject',
] as const;

export type BlockType = (typeof BLOCK_TYPES)[number];

// 1. Rich Text Content
export interface RichTextBlockContent {
  text?: string;
  html?: string;
}
export type RichTextContent = RichTextBlockContent;

// 2. Markdown Content
export interface MarkdownBlockContent {
  markdown: string;
}
export type MarkdownContent = MarkdownBlockContent;

// 3. Drawing Content
export interface DrawingStroke {
  color: string;
  width: number;
  points: Array<[number, number, number?]>; // [x, y, pressure?]
  isEraser: boolean;
}

export interface DrawingBlockContent {
  strokes: DrawingStroke[];
  dataUrl?: string; // Optional cached export
}
export type DrawingContent = DrawingBlockContent;

// 4. Checklist Content
export interface ChecklistItem {
  id: string;
  text: string;
  checked: boolean;
}

export interface ChecklistBlockContent {
  items: ChecklistItem[];
}
export type ChecklistContent = ChecklistBlockContent;

// 5. Table Content
export interface TableBlockContent {
  headers: string[];
  rows: string[][];
}
export type TableContent = TableBlockContent;

// 6. Media Content
export type MediaType = 'audio' | 'image' | 'pdf' | 'video';

export interface MediaBlockContent {
  mediaType: MediaType;
  url: string;
  fileName?: string;
  title?: string;
  caption?: string;
  duration?: number; // in seconds
  peaks?: number[];  // normalized waveform peaks [0.0 - 1.0]
  width?: number;
  height?: number;
  alt?: string;
  pageCount?: number;
  sizeBytes?: number;
}
export type MediaContent = MediaBlockContent;

// 7. Embed Content
export type EmbedProvider = 'spotify' | 'soundcloud' | 'youtube' | 'generic';

export interface EmbedBlockContent {
  url: string;
  provider?: EmbedProvider;
  title?: string;
  description?: string;
  thumbnailUrl?: string;
  embedUrl?: string;
  authorName?: string;
}
export type EmbedContent = EmbedBlockContent;

// 8. Code Content
export type CodeLanguage =
  | 'typescript'
  | 'javascript'
  | 'python'
  | 'rust'
  | 'css'
  | 'html'
  | 'sql'
  | 'json'
  | 'markdown'
  | 'plaintext';

export interface CodeBlockContent {
  language: CodeLanguage;
  code: string;
}
export type CodeContent = CodeBlockContent;

export type BlockContentMap = {
  rich_text: RichTextBlockContent;
  markdown: MarkdownBlockContent;
  drawing: DrawingBlockContent;
  checklist: ChecklistBlockContent;
  table: TableBlockContent;
  media: MediaBlockContent;
  embed: EmbedBlockContent;
  code: CodeBlockContent;
  subproject: { targetProjectId: string };
};

export interface Block<T extends BlockType = BlockType> {
  id: string;
  projectId: string;
  type: T;
  content: BlockContentMap[T];
  order: number;
  canvasX: number | null;
  canvasY: number | null;
  canvasW: number | null;
  canvasH: number | null;
  canvasZ: number | null;
  createdAt: string | number | Date;
  updatedAt: string | number | Date;
  version?: number;
}

export interface PresenceCursor {
  x: number;
  y: number;
  blockId?: string;
}

export interface PresenceUser {
  userId: string;
  userName: string;
  color: string;
  cursor?: PresenceCursor;
  lastUpdated?: number;
}

export const COLLAB_PALETTE = [
  '#FFDE59', // Studio Gold
  '#00F0FF', // Cyan Neon
  '#FF5376', // Coral Punch
  '#A855F7', // Electric Violet
  '#10B981', // Synth Emerald
  '#F59E0B', // Warm Amber
  '#EC4899', // Pink Rose
  '#38BDF8', // Sky Blue
];

export function getUserColor(userId: string): string {
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    hash = (hash + userId.charCodeAt(i)) % COLLAB_PALETTE.length;
  }
  return COLLAB_PALETTE[hash];
}
